#include "ViewerRuntime.h"
void RunV064Tests(const fs::path& root,std::ostream& report){
    auto check=[&](bool ok,const char* text){if(!ok)throw std::runtime_error(text);report<<"PASS: v064 "<<text<<std::endl;};
    int queries=0;bool systemDark=true;auto query=[&](){++queries;return systemDark;};
    auto first=InitialViewerSettings(std::nullopt,query);check(first.darkTheme&&first.autoThumbnails&&queries==1,"first launch inherits Windows dark preference and keeps new-install defaults");
    systemDark=false;check(!InitialViewerSettings(std::nullopt,query).darkTheme&&queries==2,"first launch inherits Windows light preference");
    systemDark=true;check(InitialViewerSettings(std::string(R"({"version":1})"),query).darkTheme,"old settings without a theme inherit the Windows preference");
    queries=0;auto light=InitialViewerSettings(std::string(R"({"version":4,"darkTheme":false})"),query);systemDark=false;auto dark=InitialViewerSettings(std::string(R"({"version":4,"darkTheme":true})"),query);check(!light.darkTheme&&dark.darkTheme&&queries==0,"explicit light and dark choices skip the system query");
    auto fail=[]()->bool{throw std::runtime_error("unavailable Windows API");};check(!InitialViewerSettings(std::nullopt,fail).darkTheme&&!InitialViewerSettings(std::string(R"({"version":4})"),fail).darkTheme,"Windows query failure falls back to light mode");
    for(auto bytes:{std::string(),std::string("broken"),std::string(R"({"version":4,"darkTheme":"bad"})")}){queries=0;bool rejected=false;try{InitialViewerSettings(bytes,query);}catch(...){rejected=true;}check(rejected&&queries==0,"corrupt existing settings remain errors instead of becoming a fresh install");}
    check(!DarkThemeFromForeground(0,0,0)&&DarkThemeFromForeground(255,255,255)&&!DarkThemeFromForeground(128,128,128)&&DarkThemeFromForeground(129,129,129),"official foreground classification distinguishes both modes and the threshold");
    auto folder=root/L"v064-settings";fs::create_directories(folder);auto file=folder/L"settings.json";fs::remove(file);
    WriteSettingsSection(folder,L"ocr",R"({"version":1,"fps":5,"seconds":10})");auto bytes=[&](){std::ifstream input(file,std::ios::binary);return std::string((std::istreambuf_iterator<char>(input)),{});};auto json=JsonObject::Parse(winrt::to_hstring(bytes()));check(!json.HasKey(L"darkTheme")&&json.HasKey(L"ocr"),"saving OCR before the viewer does not pin an unchosen light default");
    systemDark=true;auto loaded=InitialViewerSettings(bytes(),query);check(loaded.darkTheme,"section-first settings can still inherit the initial Windows mode");WriteViewerSettingsFile(file,SerializeViewerSettings(loaded));systemDark=false;queries=0;auto restart=InitialViewerSettings(bytes(),query);check(restart.darkTheme&&queries==0&&JsonObject::Parse(winrt::to_hstring(bytes())).HasKey(L"ocr"),"the chosen startup mode persists without losing independent settings sections");
    ViewerSettings history;history.darkTheme=false;history.backgroundPath=L"背景.png";history.backgroundCopies={{history.backgroundPath,L"0123456789abcdef0123456789abcdef"}};history.backgroundThemes[history.backgroundPath]=true;systemDark=true;auto saved=InitialViewerSettings(SerializeViewerSettings(history),query);check(!saved.darkTheme&&saved.backgroundThemes.at(history.backgroundPath),"saved viewer mode and per-image history preferences are both preserved");
    bool live=false,available=false;auto result=InitialViewerSettings(std::nullopt,[&](){live=DetectWindowsDarkTheme();available=true;return live;});check(result.darkTheme==(available?live:false),"live Windows query is used when available and otherwise safely falls back");report<<"INFO: v064 Windows query available="<<available<<" inferred dark="<<result.darkTheme<<" (OS settings unchanged)"<<std::endl;
}
